import json, sys

def brief(s, n=200):
    s = str(s)
    return s[:n] + ('…' if len(s) > n else '')

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception as e:
                print(f"[PARSE ERROR: {e}]")
                continue
            ts = d.get('timestamp', '')
            typ = d.get('type', '')
            msg = d.get('message', {})
            role = msg.get('role', typ)
            content = msg.get('content', d.get('attachment'))
            if isinstance(content, str):
                print(f"{ts} [{role}] TEXT: {brief(content, 400)}")
            elif isinstance(content, list):
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    btype = block.get('type')
                    if btype == 'text':
                        print(f"{ts} [{role}] TEXT: {brief(block.get('text',''), 400)}")
                    elif btype == 'tool_use':
                        print(f"{ts} [{role}] TOOL_USE {block.get('name')}: {brief(block.get('input'), 200)}")
                    elif btype == 'tool_result':
                        c = block.get('content')
                        print(f"{ts} [{role}] TOOL_RESULT: {brief(c, 150)}")
                    elif btype == 'thinking':
                        print(f"{ts} [{role}] THINKING: {brief(block.get('thinking',''), 200)}")
            elif isinstance(content, dict):
                print(f"{ts} [{role}] ATTACH {content.get('type')}: {brief(content.get('content') or content.get('stdout',''), 200)}")

if __name__ == '__main__':
    main(sys.argv[1])

